30	type agentHomesFile struct {
31		Version int                          `json:"version"`
32		Homes   map[types.AgentType][]string `json:"homes,omitempty"`
33	}
34	
35	// ErrUntrustedAgentHome is returned, wrapped, by ResolveTrustedHome for a home
36	// that is neither the agent's active home nor recorded in the per-user
37	// registry.
38	var ErrUntrustedAgentHome = errors.New("agent home is not the active home or a recorded one")
39	
40	// RememberAgentHome records home in the per-user registry as the most recently
41	// used home of agentType. home must be absolute and exist; its canonical form
42	// (see filepath.EvalSymlinks) is recorded, so aliases of one directory share
43	// an entry.
44	//
45	// When the registry changes, entries that are no longer directories are
46	// dropped (entries that cannot be checked are kept) and at most
47	// maxHomesPerAgent are kept, evicting the least recently used. When home is
48	// already the most recent entry, the registry is not rewritten. A registry
49	// that cannot be read or parsed, or has an unsupported version, is not
50	// overwritten, and its error is returned.
51	//
52	// Only a home resolved from the user's environment may be recorded, never one
53	// read from session state, because ResolveTrustedHome trusts recorded homes.
54	// The registry is not locked: of two concurrent calls one update may be lost,
55	// until a later call records it again.
56	func RememberAgentHome(agentType types.AgentType, home string) error {
57		if err := requireAbsoluteHome(home); err != nil {
58			return err
59		}
60		canonical, err := filepath.EvalSymlinks(filepath.Clean(home))
61		if err != nil {
62			return fmt.Errorf("resolve agent home: %w", err)
63		}
64	
65		root, err := userdirs.ConfigRoot()
66		if err != nil {
67			return fmt.Errorf("open config directory: %w", err)
68		}
69		file, err := readAgentHomesFile(root)
70		if err != nil {
71			return err
72		}
73		recorded := file.Homes[agentType]
74		if len(recorded) > 0 && sameDir(recorded[0], canonical) {
75			return nil
76		}
77	
78		homes := make([]string, 0, len(recorded)+1)
79		homes = append(homes, canonical)
80		for _, entry := range recorded {
81			if sameDir(entry, canonical) || homeIsGone(entry) {
82				continue
83			}
84			homes = append(homes, entry)
85		}
86		if len(homes) > maxHomesPerAgent {
87			homes = homes[:maxHomesPerAgent]
88		}
89		if file.Homes == nil {
90			file.Homes = make(map[types.AgentType][]string)
91		}
92		file.Version = agentHomesVersion
93		file.Homes[agentType] = homes
94	
95		data, err := jsonutil.MarshalIndentWithNewline(file, "", "  ")
96		if err != nil {
97			return fmt.Errorf("marshal agent homes: %w", err)
98		}
99		if err := jsonutil.WriteFileAtomicIn(root, agentHomesFileName, data, 0o600); err != nil {
100			return fmt.Errorf("write agent homes: %w", err)
101		}
102		return nil
103	}
104

	}
	return "v" + version
}

func displayVersion(version string) string {
	return strings.TrimPrefix(version, "v")
}

func releaseNotesURL(version string) string {
	return downloadsURL + "/tag/" + versionCacheKey(version)
}

// printNotification prints the version update notification to the user.
func printNotification(w io.Writer, current, latest string) {
	fmt.Fprintf(w, "\nUpdate available! %s -> %s\nRelease notes: %s\n",
		displayVersion(current), displayVersion(latest), releaseNotesURL(latest))
}
